import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const {
    textContent = {},
    visual = { colors: {}, typography: {} },
    scenePosition = { x: 0, y: 0, z: 0 }
  } = config;

  const colors = visual.colors || {};
  const typo = visual.typography || {};

  // Apply scene position
  group.position.set(scenePosition.x || 0, scenePosition.y || 0, scenePosition.z || 0);

  // Background plate (7 × 5.5 units)
  const bgGeom = new THREE.PlaneGeometry(7, 5.5);
  const bgMat = new THREE.MeshBasicMaterial({
    color: colors.background || '#0b0b10',
    side: THREE.DoubleSide
  });
  const bgPlane = new THREE.Mesh(bgGeom, bgMat);
  bgPlane.position.z = -0.1;
  group.add(bgPlane);

  // Text element specifications
  const textSpecs = [
    {
      content: textContent.kicker || 'NOVA ATELIER / JOURNAL',
      position: [-3.1, 1.7, 0],
      typoKey: 'kicker'
    },
    {
      content: textContent.heroLine1 || 'PRECISION IS',
      position: [-3.1, 0.9, 0],
      typoKey: 'hero'
    },
    {
      content: textContent.heroLine2 || 'A HABIT.',
      position: [-3.1, 0.25, 0],
      typoKey: 'hero'
    },
    {
      content: textContent.body || 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
      position: [-3.1, -0.8, 0],
      typoKey: 'body'
    },
    {
      content: textContent.caption || 'ISSUE 12 / JULY 2026',
      position: [-3.1, -1.9, 0],
      typoKey: 'caption'
    }
  ];

  // Create MSDF text objects
  const textObjects = [];
  textSpecs.forEach((spec) => {
    const typoCfg = typo[spec.typoKey] || {};

    const textObj = ctx.fontAtlas.createText(spec.content, {
      fontFamily: typoCfg.family || 'JetBrains Mono',
      fontSize: typoCfg.fontSize || 18,
      fontWeight: typoCfg.fontWeight || 400,
      color: colors.paper || '#e8ecf2',
      letterSpacing: typoCfg.letterSpacing || 0,
      lineHeight: typoCfg.lineHeight || 1.4
    });

    textObj.position.fromArray(spec.position);
    group.add(textObj);
    textObjects.push(textObj);
  });

  // Accent underline rule (2.2 × 0.05 units, #ff2a38, emissive 1.2)
  const ruleGeom = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new THREE.MeshBasicMaterial({
    color: colors.accent || '#ff2a38',
    emissive: colors.accent || '#ff2a38',
    emissiveIntensity: 1.2,
    side: THREE.DoubleSide
  });
  const ruleMesh = new THREE.Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(-3.1 + 1.1, -0.15, 0.05);
  ruleMesh.scale.x = 0; // Animates to 1
  group.add(ruleMesh);

  // Animation timeline
  const timeline = gsap.timeline();

  // Initial offset state
  gsap.set(textObjects, { y: 0.4, opacity: 0 });

  // Rise-in with stagger (0.7s, cubic-bezier(0.215,0.61,0.355,1), 80ms stagger)
  timeline.to(
    textObjects,
    {
      y: 0,
      opacity: 1,
      duration: 0.7,
      ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
      stagger: 0.08
    },
    0
  );

  // Underline rule draws in (0.5s, cubic-bezier(0.25,0.46,0.45,0.94), starts at 0.7s)
  timeline.to(
    ruleMesh.scale,
    {
      x: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    },
    0.7
  );

  // Cleanup
  group.userData.cleanup = () => {
    timeline.kill();
    bgGeom.dispose();
    bgMat.dispose();
    ruleGeom.dispose();
    ruleMat.dispose();
    textObjects.forEach((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
  };

  return group;
}
